int receive_message_with_info(int sockfd, void *buf, size_t *buflen, int flags,
                              struct in6_addr *addr, uint32_t *ifindex, int *hoplimit) {
    struct msghdr msg = {0};
    union {
        char buf[CMSG_SPACE(sizeof(struct in6_pktinfo))];
        struct cmsghdr align;
    } cmsgbuf;
    struct iovec iov;

    iov.iov_base = buf;
    iov.iov_len = *buflen;
    msg.msg_name = addr;
    msg.msg_namelen = sizeof(struct in6_addr);
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = cmsgbuf.buf;
    msg.msg_controllen = sizeof(cmsgbuf);

    ssize_t len = recvmsg(sockfd, &msg, flags);
    if (len < 0) {
        return -1;
