int receive_ipv6_message(int sockfd, void *buf, size_t *buflen, int flags,
                         struct in6_addr *addr, uint32_t *ifindex, int *hoplimit) {
    struct msghdr msg;
    union {
        struct cmsghdr hdr;
        char data[CMSG_SPACE(sizeof(struct in6_addr)) +
                  CMSG_SPACE(sizeof(int)) +
                  CMSG_SPACE(sizeof(uint32_t))];
    } cmsgbuf;
    struct iovec iov;

    iov.iov_base = buf;
    iov.iov_len = *buflen;

    msg.msg_name = addr;
    msg.msg_namelen = sizeof(*addr);
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = cmsgbuf.data;
    msg.msg_controllen = sizeof(cmsgbuf);
    msg.msg_flags = 0;

    ssize_t recv_len = recvmsg(sockfd, &msg, flags);
    if (recv_len < 0)
        return -errno;

    *buflen = recv_len;

    struct cmsghdr *cmsg;
    for (cmsg = CMSG_FIRSTHDR(&msg); cmsg != NULL;
         cmsg = CMSG_NXTHDR(&msg, cmsg)) {
        if (cmsg->cmsg_level == IPPROTO_IPV6) {
            if (cmsg->cmsg_type == IPV6_HOPLIMIT && hoplimit != NULL) {
                *hoplimit = *(int *)CMSG_DATA(cmsg);
            } else if (cmsg->cmsg_type == IPV6_PKTINFO && ifindex != NULL) {
                struct in6_pktinfo *pktinfo = (struct in6_pktinfo *)CMSG_DATA(cmsg);
                *ifindex = pktinfo->ipi6_ifindex;
            }
        }
    }

    return 0;
}

