int receive_message(int sockfd, void *buf, size_t *buflen, int flags, struct in6_addr *addr, uint32_t *ifindex, int *hoplimit) {
    struct msghdr msg = {0};
    struct iovec iov;
    union {
        struct cmsghdr hdr;
        char data[CMSG_SPACE(sizeof(struct in6_pktinfo)) + CMSG_SPACE(sizeof(int))];
    } cmsgu;
    struct cmsghdr *cmsg;

    iov.iov_base = buf;
    iov.iov_len = *buflen;
    msg.msg_name = NULL;
    msg.msg_namelen = 0;
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = cmsgu.data;
    msg.msg_controllen = sizeof(cmsgu.data);

    int result = recvmsg(sockfd, &msg, flags);
    if (result < 0)
        return -1;

    *buflen = result;

    memset(addr, 0, sizeof(*addr));
    *ifindex = 0;
    *hoplimit = -1;

    for (cmsg = CMSG_FIRSTHDR(&msg); cmsg != NULL; cmsg = CMSG_NXTHDR(&msg, cmsg)) {
        if (cmsg->cmsg_level == IPPROTO_IPV6) {
            if (cmsg->cmsg_type == IPV6_PKTINFO) {
                struct in6_pktinfo *pktinfo = (struct in6_pktinfo *)CMSG_DATA(cmsg);
                *addr = pktinfo->ipi6_addr;
                *ifindex = htonl(pktinfo->ipi6_ifindex);
            } else if (cmsg->cmsg_type == IPV6_HOPLIMIT) {
                int *hl = (int *)CMSG_DATA(cmsg);
                *hoplimit = *hl;
            }
        }
    }

    return 0;
}
